package cn.linkdeck.adb;
import java.util.*;import java.io.*;
public class UpgradeCoreChecks {
 static int count;interface Op{void run()throws Exception;}static void ok(boolean b,String name){if(!b)throw new AssertionError(name);count++;System.out.println("PASS: "+name);}static void no(Op op,String name)throws Exception{try{op.run();throw new AssertionError(name);}catch(IOException e){ok(true,name);}}
 static void policy(String expected,long next,boolean present,long previous,String old,String sign,int minimum,int sdk,Set<String> abis,String target)throws Exception{InstallPolicy.check(expected,"test.app",next,present,previous,old,sign,minimum,sdk,abis,target);}
 public static void main(String[] args)throws Exception{
  String k=DeviceScope.recoveryKey("host","5555","serial","fp","TV");ok(k.equals(DeviceScope.recoveryKey("host","5555","serial","fp","TV")),"recovery scope is stable");ok(!k.equals(DeviceScope.recoveryKey("host","5556","serial","fp","TV")),"ports cannot share recovery records");ok(!k.equals(DeviceScope.recoveryKey("host","5555","other","fp","TV")),"replacement device has a separate recovery scope");ok(!k.equals(DeviceScope.recoveryKey("host","5555","serial","fp2","TV")),"firmware changes are not silently migrated");no(()->DeviceScope.recoveryKey("host","5555","unknown","fp","TV"),"unknown serial cannot auto-attribute recovery");ok(!DeviceScope.installationKey("host","5555","","fp","TV").isEmpty(),"same-transport install can use firmware identity");
  Set<String> none=Collections.emptySet(),arm=Collections.singleton("arm64-v8a");policy(null,2,true,1,"cert","cert",21,22,none,"arm64-v8a");ok(true,"compatible update accepted");policy(null,1,true,1,"cert","cert",21,22,arm,"armeabi-v7a,arm64-v8a");ok(true,"explicit same-version replacement accepted");policy(null,0,false,-1,"","cert",21,22,none,"arm64-v8a");ok(true,"versionCode zero first install accepted");no(()->policy("other.app",2,true,1,"cert","cert",21,22,none,"arm64-v8a"),"expected package mismatch rejected");no(()->policy(null,2,true,1,"old","new",21,22,none,"arm64-v8a"),"signer mismatch cannot replace current app");no(()->policy(null,1,true,2,"cert","cert",21,22,none,"arm64-v8a"),"generic downgrade is blocked");no(()->policy(null,2,true,-1,"cert","cert",21,22,none,"arm64-v8a"),"unknown installed version is not treated as absence");no(()->policy(null,2,false,-1,"","cert",26,22,none,"arm64-v8a"),"Android 5.1 minimum-SDK conflict rejected");no(()->policy(null,2,false,-1,"","cert",21,22,arm,"x86_64"),"ABI conflict rejected");no(()->policy(null,2,false,-1,"","cert",21,0,none,""),"unknown device capabilities rejected");
  PackageProbe.validate("cn.example.app");ok(true,"valid package accepted");no(()->PackageProbe.validate("app; reboot"),"shell-like package input rejected");String absent=PackageProbe.path(c->c.startsWith("pm path")?new AdbClient.Result("",1):new AdbClient.Result("package:android\npackage:other.app",0),"test.app");ok(absent.isEmpty(),"legacy exit-1 absence confirmed against listing");no(()->PackageProbe.path(c->new AdbClient.Result("permission denied",1),"test.app"),"permission error is never absence");no(()->PackageProbe.path(c->c.startsWith("pm path")?new AdbClient.Result("",1):new AdbClient.Result("package:test.app",0),"test.app"),"listed package with unreadable path stops update");
  String launch=ApplicationLauncher.command("test.app");ok(launch.indexOf("LEANBACK_LAUNCHER")<launch.indexOf("category.LAUNCHER"),"TV launcher attempted before ordinary launcher");try{ApplicationLauncher.command("test.app' ; reboot");throw new AssertionError();}catch(IllegalArgumentException e){ok(true,"launcher package cannot inject shell text");}
  System.out.println("UPGRADE CORE PASSED: "+count+" checks.");
 }
}
